   147→\subsection{Algorithms}
   148→
   149→Algorithms summarize, in readable form, the steps that comprise a computational procedure.
   150→Algorithm~\ref{algo:TwoColumns} shows an example using the \verb|algorithm2e| package.
   151→This pseudocode spans two columns.
   152→
   153→\begin{algorithm*}[hbt]
   154→	\DontPrintSemicolon
   155→	\SetKwInput{KwCompute}{Compute}
   156→	\SetKwInput{KwDefine}{Define}
   157→	\caption{Quasi $U$-Statistics}\label{algo:TwoColumns}
   158→	\KwData{The list of folders $\mathcal L$}
   159→	\KwData{The number of groups $G$.}
   160→	\KwData{The sample size per group $n_1,n_2,\dots,n_G$.}
   161→	\KwData{The data per group $\bm X_{1},\ldots,\bm X_{n_1},\bm X_{n_1+1},\ldots,\bm X_{n-n_G+1},\ldots,\bm X_{n_G}$.}
   162→	\KwData{The number of bootstrap replications $B$ (we used $200$).}
   163→	\KwCompute{Choose the kernel $\phi$ of degree two from 
   164→		\begin{align*}
   165→			\phi_1(x,y)&=|x-y|^p,\\
   166→			\phi_2(x,y)&=\mathbbm{1}\left\{|x-y|>\eta\right\}.
   167→	\end{align*}}
   168→	\KwCompute{Select $p$ for $\phi_1$, or $\eta$ for $\phi_2$, e.g., with a data-drive optimization method.}
   169→	\KwDefine{Define $T$ as
   170→		\[
   171→		T=\sum\eta_{nij}\phi(\bm X_i,\bm X_j),
   172→		\]
   173→		where the weights are given by:
   174→		\[
   175→		\eta_{nij}=\begin{cases}
   176→			1 & \text{if } i \text{ and } j \text{ belong to different groups,}\\
   177→			-\frac{(n-n_g)}{(n_g-1)} & \text{if } i \text{ and } j \text{ belong to group } g, \text{ for each } 1\leq g\leq G.
   178→		\end{cases}
   179→		\]}
   180→	\While{$\mathcal L$ has elements}{
   181→		Read the following element $\ell$ in the list $\mathcal L$\;
   182→		\If{$\ell$ is empty}{Skip to the next element\;}
   183→		\Else{
   184→			\KwCompute{Compute $T$ on the sample $\bm X_{1},\ldots,\bm X_{n_1},\bm X_{n_1+1},\ldots,\bm X_{n-n_G+1},\ldots,\bm X_{n_G}$ and store it in $T_{\text{obs}}$}
   185→			\For{$1\leq b \leq B$}{
   186→				Build the bootstrap sample $\bm X^{(b)}=\big(\bm X_{1}^{(b)},\ldots,\bm X_{n_1}^{(b)},\ldots,\bm X_{n-n_G+1}^{(b)},\ldots,\bm X_{n_G}^{(b)}\big)$\;
   187→				Compute $T^{(b)}$ with $\bm X^{(b)}$
   188→			}
   189→			Compute $q_\alpha$, the upper $\alpha$ quantile of $T^{(1)},T^{(2)},\dots, T^{(B)}$\;
   190→			\KwOut{Decision: reject $H_0$ if $T_{\text{obs}}>q_\alpha$.}
   191→			Remove the current set from the list $\mathcal L$\;
   192→		}
   193→	}
   194→\end{algorithm*}
